    type Output = PyObject<'p>;

    #[inline]
    fn index<'a>(&'a self, index: &uint) -> &'a PyObject<'p> {
        // use as_slice() to use the normal Rust bounds checking when indexing
        self.as_slice()[*index]
    }
}

